begin;
create temporary table personal_test_context as select (select id from public.profiles limit 1) uid,gen_random_uuid() future_match,gen_random_uuid() past_match,gen_random_uuid() other_uid;
grant select on personal_test_context to authenticated,anon;
insert into public.matches select (jsonb_populate_record(null::public.matches,to_jsonb(m)||jsonb_build_object('id',c.future_match,'kickoff',now()+interval '58 minutes','status','scheduled','goal_fixture_id',null,'goal_fixture_api_id',null))).* from public.matches m cross join personal_test_context c where home_club_id is not null limit 1;
insert into public.matches select (jsonb_populate_record(null::public.matches,to_jsonb(m)||jsonb_build_object('id',c.past_match,'kickoff',now()-interval '1 day','status','finished','home_score',4,'away_score',0,'goal_fixture_id',null,'goal_fixture_api_id',null))).* from public.matches m cross join personal_test_context c where home_club_id is not null limit 1;
insert into storage.objects(bucket_id,name,owner_id) select 'fan-match-albums',uid::text||'/'||past_match::text||'/rollback-test.png',uid::text from personal_test_context;
select set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated')::text,true) from personal_test_context;
set local role authenticated;
do $$declare c record;blocked boolean;summary jsonb;begin
 select * into c from personal_test_context;
 insert into public.fan_match_alerts(user_id,match_id,enabled,reminder_hour) values(c.uid,c.future_match,true,true);
 perform public.save_fan_diary(c.past_match,'{"private_note":"rollback-only-private-note","away_trip_note":"rollback-only-trip","checklist":["צעיף"],"checklist_items":["צעיף","פריט חדש"]}');
 perform public.save_fan_diary(c.past_match,jsonb_build_object('watched_at',now()));
 if (select private_note<>'rollback-only-private-note' or away_trip_note<>'rollback-only-trip' or watched_at is null from public.fan_match_diary where user_id=c.uid and match_id=c.past_match) then raise exception 'Partial patch lost private diary fields';end if;
 insert into public.fan_saved_items(user_id,kind,entity_id) select c.uid,'player',id from public.players limit 1;
 insert into public.fan_album_photos(user_id,match_id,storage_path,caption) values(c.uid,c.past_match,c.uid::text||'/'||c.past_match::text||'/rollback-test.png','rollback-only-caption');
 if not exists(select 1 from storage.objects where bucket_id='fan-match-albums' and name=c.uid::text||'/'||c.past_match::text||'/rollback-test.png') then raise exception 'Owner cannot read album metadata';end if;
 insert into public.match_attendance(user_id,match_id,supported_club_id) select c.uid,c.past_match,home_club_id from public.matches where id=c.past_match;
 summary:=public.fan_attendance_summary();if (summary->>'wins')::int<1 or (summary->>'graded')::int<1 then raise exception 'Attendance result direction incorrect';end if;
 perform public.set_notification_preferences('{"quiet_enabled":false,"push_enabled":true,"selected_games_only":true}');
 blocked:=false;begin perform public.set_notification_preferences('{"owner":true}');exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Unknown preference accepted';end if;
 blocked:=false;begin perform public.save_fan_diary(c.future_match,jsonb_build_object('watched_at',now()));exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Future match watched marker accepted';end if;
 blocked:=false;begin perform public.queue_match_reminders();exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'User can dispatch reminders';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',c.other_uid,'role','authenticated')::text,true);
 if exists(select 1 from public.fan_match_diary where match_id=c.past_match) or exists(select 1 from public.fan_album_photos where match_id=c.past_match) or exists(select 1 from public.fan_match_alerts where match_id=c.future_match) or exists(select 1 from storage.objects where bucket_id='fan-match-albums' and name=c.uid::text||'/'||c.past_match::text||'/rollback-test.png') then raise exception 'Cross-account private read allowed';end if;
 blocked:=false;begin insert into public.fan_match_diary(user_id,match_id) values(c.uid,c.future_match);exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'Cross-account write allowed';end if;
end$$;
select set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','anon')::text,true) from personal_test_context;
set local role anon;
do $$declare c record;begin select * into c from personal_test_context;if exists(select 1 from storage.objects where bucket_id='fan-match-albums' and name=c.uid::text||'/'||c.past_match::text||'/rollback-test.png') then raise exception 'Anonymous private album read allowed';end if;end$$;
set local role postgres;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
do $$declare c record;prefs jsonb;begin
 select * into c from personal_test_context;
 perform public.queue_match_reminders();
 if not exists(select 1 from public.notification_inbox where user_id=c.uid and event_key='reminder:'||c.future_match and kind='reminder') then raise exception 'Personal hour reminder not queued';end if;
 perform public.queue_match_reminders();
 if (select count(*) from public.notification_inbox where user_id=c.uid and event_key='reminder:'||c.future_match)<>1 then raise exception 'Duplicate reminder queued';end if;
 prefs:='{"quiet_enabled":true,"quiet_start":22,"quiet_end":8,"quiet_timezone":"Asia/Jerusalem"}';
 if not public.fan_quiet_now(prefs,'2026-10-14T00:00:00Z') or public.fan_quiet_now(prefs,'2026-10-14T12:00:00Z') or public.fan_quiet_now(prefs,'2026-10-14T05:00:00Z') then raise exception 'Quiet hours timezone/boundary incorrect';end if;
 if public.fan_pref_bool('{"goals":"invalid"}','goals',false) then raise exception 'Malformed preference causes unsafe behavior';end if;
 update public.profiles set notification_prefs=coalesce(notification_prefs,'{}'::jsonb)||jsonb_build_object('quiet_enabled',true,'quiet_start',0,'quiet_end',0,'quiet_timezone','UTC') where id=c.uid;
 perform public.claim_push_notifications(0);
 if not exists(select 1 from public.notification_inbox where user_id=c.uid and event_key='reminder:'||c.future_match and push_suppressed_at is not null and push_suppression_reason='quiet_hours' and push_sent_at is null) then raise exception 'Quiet reminder suppression is not recorded honestly';end if;
end$$;
rollback;
select jsonb_build_object('passed',true,'rolled_back',true,'sent_notifications',false,'uploaded_photos',false,'checks',jsonb_build_array('own diary and album reads','partial diary patch preserves notes','private image metadata ownership','cross-account isolation','cross-account writes denied','anonymous album denied','attendance home/away direction','unknown preference rejected','future watched marker rejected','service-only reminder dispatch','hour reminder queued once','timezone-aware quiet interval','quiet suppression without fake delivery')) as result;
